import React from 'react';
import { Animate } from 'react-move';
import { renderChildren } from '@fiverr-private/ui_utils';
import type { ScaleFadeProps, TransitionProps } from '../../types';
import { useTransitionEvents } from '../../hooks';
import variants from './variants';

const ScaleFade = ({
  reverse = true,
  initialScale = 0.95,
  initialOpacity = 0,
  delay,
  duration = 'fast2',
  easing = 'easeInOut',
  unmountOnExit,
  in: isOpen = true,
  onAnimationStart,
  onAnimationEnd,
  children,
}: TransitionProps & ScaleFadeProps) => {
  const custom = { initialScale, initialOpacity, delay, duration, easing };
  const transitionConfig = isOpen ? variants.enter(custom) : variants.exit(custom);

  const { getEventsHandler } = useTransitionEvents({ onAnimationStart, onAnimationEnd, isOpen, unmountOnExit });

  return (
    <Animate
      show={unmountOnExit ? isOpen : true}
      start={variants.exit(custom)}
      enter={{
        ...transitionConfig,
        ...getEventsHandler('enter'),
      }}
      update={{
        ...transitionConfig,
        ...getEventsHandler('update'),
      }}
      leave={{
        ...variants.exit(custom),
        ...getEventsHandler('leave'),
      }}
    >
      {({ scale, ...rest }) =>
        renderChildren(children, {
          style: {
            ...(children.props.style || {}),
            ...rest,
            display: rest.opacity === 0 ? 'none' : undefined,
            transform: isOpen || reverse ? `scale(${scale})` : 'scale(1)',
          },
        })
      }
    </Animate>
  );
};

ScaleFade.displayName = 'ScaleFade';

export default ScaleFade;
