import { getValueOrField } from '../../utils';
import { DURATION, EASING } from '../../constants';
import type {
    Duration,
    DurationType,
    Easing,
    EasingType,
    ScaleFadeProps,
    VariantsKeys,
    VariantsType,
} from '../../types';

const getTiming = (
    key: VariantsKeys,
    duration: DurationType = 'fast2',
    easing: EasingType = 'easeInOut',
    delay?: DurationType
) => ({
    duration: DURATION[getValueOrField(duration, key) as Duration],
    ease: EASING[getValueOrField(easing, key) as Easing],
    delay: DURATION[getValueOrField(delay, key) as Duration],
});

const variants: VariantsType<ScaleFadeProps> = {
    enter: ({ delay, duration, easing }) => ({
        opacity: [1],
        scale: [1],
        timing: getTiming('enter', duration, easing, delay),
    }),
    exit: ({ initialScale, initialOpacity, delay, duration, easing }) => ({
        opacity: [initialOpacity],
        scale: [initialScale],
        timing: getTiming('exit', duration, easing, delay),
    }),
};

export default variants;
